const int32_t rf_roots[RF_N_TREES] = {0,123,236,395,512,653,800,975,1150,1303,1464,1607,1754,1913,2122,2259,2438,2563,2732,2877,3066,3193,3344,3491,3636,3773,3956,4109,4234,4379,4554,4715,4858,5007,5174,5351,5494,5633,5776,5899,6088,6235,6434,6549,6710,6871,7004,7127,7264,7401,7584,7753,7908,8083,8232,8409,8542,8661,8810,8999,9140,9297,9450,9625,9766,9887,10060,10201,10388,10555,10704,10831,10978,11127,11276,11399,11536,11705,11910,12073,12238,12413,12566,12679,12848,12973,13110,13273,13404,13567,13704,13845,13980,14143,14298,14501,14628,14793,14944,15095,15208,15375,15512,15679,15868,16003,16134,16309,16444,16639,16808,16965,17122,17251,17390,17527,17644,17793,17924,18083,18202,18353,18514,18643,18800,18979,19110,19219,19358,19525,19686,19855,19974,20103,20252,20405,20594,20739,20910,21071,21194,21341,21498,21643,21814,21951,22098,22245,22396,22551,22684,22857,23012,23159,23294,23421,23546,23723,23888,24047,24186,24295,24448,24615,24746,24921,25048,25209,25330,25489,25660,25823,25988,26105,26302,26455,26596,26767,26908,27087,27238,27413,27562,27703,27834,27975,28110,28309,28488,28673,28858,29007,29170,29321,29456,29609,29756,29907,30064,30213};

static int tree_predict(const float x[RF_N_FEATURES], int root, float out[RF_N_CLASSES]) {
  int node = root;
  while (rf_left[node] != -1) {
    int f = rf_feature[node];
    node = (x[f] <= rf_threshold[node]) ? rf_left[node] : rf_right[node];
  }
  uint32_t total = 0;
  for (int c=0;c<RF_N_CLASSES;c++) total += rf_counts[node][c];
  if (total == 0) total = 1;
  for (int c=0;c<RF_N_CLASSES;c++) out[c] = (float)rf_counts[node][c] / (float)total;
  return 0;
}

int rf_predict(const float features[RF_N_FEATURES], float probabilities[RF_N_CLASSES]) {
  for (int c=0;c<RF_N_CLASSES;c++) probabilities[c] = 0.0f;
  float p[RF_N_CLASSES];
  for (int t=0;t<RF_N_TREES;t++) {
    tree_predict(features, rf_roots[t], p);
    for (int c=0;c<RF_N_CLASSES;c++) probabilities[c] += p[c];
  }
  int best = 0;
  for (int c=0;c<RF_N_CLASSES;c++) {
    probabilities[c] /= RF_N_TREES;
    if (probabilities[c] > probabilities[best]) best = c;
  }
  return best;
}
